protocol Describable { var name: String { get } }
extension Describable {
    func describe() -> String { "I'm \(name)" }
}
struct Dog: Describable { let name = "Fido" }

protocol P { func a() }
extension P {
    func a() { print("P.a") }  // requirement default
    func b() { print("P.b") }  // not a requirement
}

func largest<T: Comparable>(_ xs: [T]) -> T? {
    xs.max()
}
extension Array: Describable where Element: Describable { ... }

protocol Store {
    associatedtype Item
    func save(_ item: Item)
}
func sum(_ xs: some Collection<Int>) -> Int { xs.reduce(0, +) }

